import{_ as a,o as s,c as r,ag as n}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Primeros pasos","description":"","frontmatter":{},"headers":[],"relativePath":"es/getting-started.md","filePath":"es/getting-started.md"}'),o={name:"es/getting-started.md"};function t(i,e,l,c,p,d){return s(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h1><p>Esta página te lleva desde la compra hasta la primera vez que abres el panel de ajustes en el juego. Es igual para todos los scripts Nayretis.</p><h2 id="comprar-y-descargar" tabindex="-1">Comprar y descargar <a class="header-anchor" href="#comprar-y-descargar" aria-label="Permalink to &quot;Comprar y descargar&quot;">​</a></h2><ol><li>Compra el script en la <a href="https://www.nayretis.com" target="_blank" rel="noreferrer">tienda Nayretis</a>. El pago lo gestiona Tebex.</li><li>Inicia sesión en <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> con la cuenta Cfx.re que usaste al pagar. El script y <code>nay_lib</code> aparecen en tus recursos concedidos (granted assets).</li><li>Descarga los dos. <code>nay_lib</code> viene con cada script Nayretis y nunca se vende por separado.</li></ol><p>Los scripts están protegidos por el escrow de Cfx: solo arrancan en un servidor cuya clave de licencia pertenece a la cuenta Cfx.re que los posee.</p><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><ul><li><a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>, iniciado y conectado a tu base de datos.</li><li>Uno de los frameworks compatibles: ESX Legacy, QBCore, QBox u ox_core. Consulta <a href="/es/bridge/">Bridge</a> para los inventarios, targets y notificaciones.</li></ul><h2 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h2><p>Copia la carpeta <code>nay_lib</code> y la carpeta del script en tu carpeta <code>resources</code>. En <code>server.cfg</code>, inícialos después de los recursos de tu framework, inventario y target:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span># your framework, inventory and target resources here</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p><code>nay_lib</code> se instala una sola vez, sea cual sea el número de scripts Nayretis que uses. Mantenlo antes de todos los scripts Nayretis.</p><h2 id="primer-arranque" tabindex="-1">Primer arranque <a class="header-anchor" href="#primer-arranque" aria-label="Permalink to &quot;Primer arranque&quot;">​</a></h2><p>Inicia el servidor. Las tablas de la base de datos se crean automáticamente, no hay ningún archivo SQL que importar. En la consola deberías ver:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[script:nay_lib] [INFO] Bridge ready: framework=qbox inventory=ox_inventory</span></span>
<span class="line"><span>[script:nay_lib] [INFO] Ready: settings, permissions and migrations loaded</span></span></code></pre></div><p>Los nombres del framework y del inventario corresponden a lo que usa tu servidor.</p><h2 id="darte-acceso" tabindex="-1">Darte acceso <a class="header-anchor" href="#darte-acceso" aria-label="Permalink to &quot;Darte acceso&quot;">​</a></h2><p>Los ajustes se editan en el juego con <code>/nay</code>. Da acceso completo al grupo admin en <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span></code></pre></div><p>O concede el acceso a un jugador desde la consola del servidor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license &lt;license&gt; nay.admin</span></span></code></pre></div><p>Después entra en el servidor y escribe <code>/nay</code>. Más opciones en la página <a href="/es/nay-lib/permissions">Permisos</a>.</p><h2 id="siguientes-pasos" tabindex="-1">Siguientes pasos <a class="header-anchor" href="#siguientes-pasos" aria-label="Permalink to &quot;Siguientes pasos&quot;">​</a></h2><ul><li>Descubre el <a href="/es/nay-lib/panel">panel /nay</a>: idiomas, tema, permisos, API y webhooks.</li><li>Configura <a href="/es/car-wash/">Car Wash</a>.</li><li>¿Algo no arranca? Lee las <a href="/es/faq">preguntas frecuentes</a>.</li></ul>`,23)])])}const g=a(o,[["render",t]]);export{h as __pageData,g as default};
